</style>
</head>
<body>
<div id="score">נקודות: <span id="points">0</span></div>
<div id="circle">לחץ!</div>

<div id="controls">
 <button id="reset">אפס</button>
 <button id="theme">מצב כהה/בהיר</button>
</div>

<script>
 const pointsEl = document.getElementById('points');
 const circle = document.getElementById('circle');
 const resetBtn = document.getElementById('reset');
 const themeBtn = document.getElementById('theme');

 // Load saved state
 let points = Number(localStorage.getItem('circlePoints')) || 0;
 let darkMode = localStorage.getItem('darkMode') === 'true';
 updateScore();
 applyTheme();

 circle.addEventListener('click', () => {
 points += 1;
 updateScore();
 // simple animation feedback
 circle.style.transform = 'scale(1.1)';
 setTimeout(() => circle.style.transform = '', 150);
 });

 resetBtn.addEventListener('click', () => {
 points = 0;
 updateScore();
 });

 themeBtn.addEventListener('click', () => {
 darkMode = !darkMode;
 applyTheme();
 });

 function updateScore() {
 pointsEl.textContent = points;
 localStorage.setItem('circlePoints', points);
 }

 function applyTheme() {
 if (darkMode) {
 document.body.style.background = getComputedStyle(document.documentElement).getPropertyValue('--bg-dark');
 document.body.style.color = '#eee';
 } else {
 document.body.style.background = getComputedStyle(document.documentElement).getPropertyValue('--bg-light');
 document.body.style.color = '#222';
 }
 localStorage.setItem('darkMode', darkMode);
 }
</script>
</html>
```

- לוחצים על העיגול ומקבלים נקודה בכל לחיצה. 
- כפתור **אפס** מאפס את הניקוד. 
- כפתור **מצב כהה/בהיר** משנה את העיצוב. 
- מצב המשחק נשמר ב‑`localStorage`, כך שהנקודות והנושא נשמרים גם אחרי רענון הדף.

נהר שלום, עדכנתי את המשחק! הוספתי שדה להזנת קוד סודי. אם מזינים את הקוד **1234** ולוחצים על הכפתור "הפעל קוד", מקבלים בונוס של **100 נקודות**! 🎮✨

