 submitCodeBtn.addEventListener('click', checkCode);
 codeInput.addEventListener('keypress', (e) => {
 if (e.key === 'Enter') checkCode();
 });

 function checkCode() {
 const code = codeInput.value.trim();
 if (code === '1234') {
 points += 100;
 updateScore();
 showMessage('🎉 הקוד נכון! קיבלת 100 נקודות בונוס!', 'msg-success');
 codeInput.value = '';
 } else if (code === '') {
 showMessage('יש להזין קוד', 'msg-error');
 } else {
 showMessage('❌ קוד שגוי, נסה שוב', 'msg-error');
 }
 }

 function showMessage(text, className) {
 messageEl.textContent = text;
 messageEl.className = className;
 setTimeout(() => {
 messageEl.textContent = '';
 messageEl.className = '';
 }, 3000);
 }

 // איפוס
 resetBtn.addEventListener('click', () => {
 points = 0;
 updateScore();
 showMessage('הנקודות אופסו', '');
 });

 // שינוי עיצוב
 themeBtn.addEventListener('click', () => {
 darkMode = !darkMode;
 applyTheme();
 });

 function updateScore() {
 pointsEl.textContent = points;
 localStorage.setItem('circlePoints', points);
 }

 function applyTheme() {
 if (darkMode) {
 document.body.classList.add('dark-mode');
