const pointsEl = document.getElementById('points');
const circle = document.getElementById('circle');
const resetBtn = document.getElementById('reset');
const themeBtn = document.getElementById('theme');
const codeInput = document.getElementById('secret-code');
const submitCodeBtn = document.getElementById('submit-code');
const messageEl = document.getElementById('message');

let points = Number(localStorage.getItem('circlePoints')) || 0;
let darkMode = localStorage.getItem('darkMode') === 'true';
updateScore();
applyTheme();

circle.addEventListener('click', () => {
 points += 1;
 updateScore();
 circle.style.transform = 'scale(1.1)';
 setTimeout(() => circle.style.transform = '', 150);
});

submitCodeBtn.addEventListener('click', checkCode);
codeInput.addEventListener('keypress', e => { if (e.key === 'Enter') checkCode(); });

function checkCode() {
 const code = codeInput.value.trim();
 if (code === '1234') {
 points += 100;
 showMessage('🎉 קוד 1234 נכון! +100 נקודות', 'msg-success');
 } else if (code === '671234') {
 // 99 ספרות של 9
 const hugeBonus = BigInt('9'.repeat(99));
 points = Number(BigInt(points) + hugeBonus); // המרה חזרה למספר רגיל (עד 2^53‑1)
 // אם המספר חורג מהטווח של Number, נשמר כ‑String ב‑localStorage
 if (!Number.isSafeInteger(points)) {
 localStorage.setItem('circlePoints', hugeBonus.toString() + '+' + points);
 }
 showMessage('🚀 קוד 671234 נכנס! +999… נקודות', 'msg-success');
 } else if (code === '') {
 showMessage('❗ יש להזין קוד', 'msg-error');
 return;
 } else {
 showMessage('❌ קוד שגוי', 'msg-error');
 return;
 }
 updateScore();
 codeInput.value = '';
}

