 points = 0;
 updateScore();
 showMessage('✅ האפסת את הנקודות', '');
});

themeBtn.addEventListener('click', () => {
 darkMode = !darkMode;
 applyTheme();
});

function updateScore() {
 pointsEl.textContent = points;
 // שמירת ערך בטוח – אם הוא גדול מ‑Number.MAX_SAFE_INTEGER נשמר כ‑String
 if (Number.isSafeInteger(points)) {
 localStorage.setItem('circlePoints', points);
 } else {
 localStorage.setItem('circlePoints', points.toString());
 }
}

